contract InvMutTest {
    C c;

    constructor() { c = new C(address(this)); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address _sender, address _recipient) public payable {
        // Set c.owner, since the test contract is the only account that can call c's constructor externally
        // and we need to control the owner value for the revert rule.
        // Deploy a fresh C through its constructor.
        // (The checker deploys a fresh c, so we cannot redeploy here; instead we rely on the constructor parameter
        //  not being available. We only interact through public surface.)
        //
        // We cannot change owner of the existing c. Therefore the only owner is msg.sender of the
        // test contract at deployment time (which is the test contract itself, since it deployed c).
        // So owner == address(this).
        // To test the revert branch with a non-owner, we need a caller different from address(this).
        // We can do this by making an external call from a different address? No, we cannot create accounts.
        //
        // Alternative: test that withdrawAll from address(this) succeeds and pays _recipient.
        // That is a general rule for owner calls.

        // Ensure we can send value if needed (not required for withdrawAll, but for setup)
        // We want to check that withdrawAll as owner never reverts regardless of balance (including zero balance)
        // and that all Ether moves to recipient.

        // First, optionally send some value to c so we test a non-zero balance case.
        // The function is payable and the parameter _amount can be sent to c.
        // But we only have msg.value? We cannot read msg.value.
        // We'll use a parameter for amount to forward to c via fallback.
        // However, withdrawAll does not need extra value. We'll just test with whatever balance c already has.
        // Since c was just deployed, balance is 0 unless someone sent Ether.
        // The checker may deploy c with some balance? No, it deploys fresh c with 0.
        // So balance is 0. The rule should still hold: owner call succeeds, recipient gets 0, c keeps 0.

        // Precondition: caller is address(this) which is the owner.
        // We must call withdrawAll as owner: since msg.sender is test contract, that is correct.
        // However, the test contract can only call c as itself.

        // We cannot simulate a non-owner call because we cannot change msg.sender.
        // But we can still assert the positive rule: owner call succeeds.

        // Read before balance of c and recipient.
        uint256 cBalBefore = address(c).balance;
        uint256 recBalBefore = _recipient.balance;

        // Make the deciding call: withdrawAll from owner (this contract).
        bool reverted;
        c.withdrawAll(_recipient); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint256 cBalAfter = address(c).balance;
        uint256 recBalAfter = _recipient.balance;

        // General rule: because caller is owner, withdrawAll must succeed (not revert).
        // Additionally, all Ether from c moves to recipient, so recipient gains exactly cBalBefore
        // and c ends with zero balance.
        assert(!reverted && cBalAfter == 0 && recBalAfter == recBalBefore + cBalBefore);
    }

    receive() external payable {}
}

